    <title>星空选项卡</title>
    <style>
      .star-choices {
        background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 50%, #0f172a 100%);
        border: 1px solid rgba(147, 197, 253, 0.3);
        border-radius: 18px;
        box-shadow:
          0 4px 24px rgba(147, 197, 253, 0.2),
          0 0 40px rgba(147, 197, 253, 0.1),
          inset 0 1px 0 rgba(147, 197, 253, 0.1);
        padding: 20px;
        position: relative;
        overflow: hidden;
      }

      .choice-item {
        background: linear-gradient(135deg, rgba(30, 58, 95, 0.5) 0%, rgba(15, 23, 42, 0.6) 100%);
        border: 1px solid rgba(147, 197, 253, 0.3);
        border-radius: 12px;
        padding: 12px 16px;
        color: #bae6fd;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        cursor: pointer;
      }

      .choice-item:hover {
        background: linear-gradient(135deg, rgba(30, 58, 95, 0.7) 0%, rgba(15, 23, 42, 0.8) 100%) !important;
        border-color: rgba(147, 197, 253, 0.5) !important;
        box-shadow:
          0 4px 20px rgba(147, 197, 253, 0.3),
          0 0 30px rgba(147, 197, 253, 0.2) !important;
        transform: translateX(4px);
      }

      .choice-item:active {
        transform: translateX(2px) scale(0.98) !important;
      }

      @keyframes stars-twinkle {
        0%,
        100% {
          opacity: 0.6;
        }
