<!doctype html>
<html lang="zh-CN">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>星空选项卡</title>
    <style>
      .star-choices {
        background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 50%, #0f172a 100%);
        border: 1px solid rgba(147, 197, 253, 0.3);
        border-radius: 18px;
        box-shadow:
          0 4px 24px rgba(147, 197, 253, 0.2),
          0 0 40px rgba(147, 197, 253, 0.1),
          inset 0 1px 0 rgba(147, 197, 253, 0.1);
        padding: 20px;
        position: relative;
        overflow: hidden;
      }

      .choice-item {
        background: linear-gradient(135deg, rgba(30, 58, 95, 0.5) 0%, rgba(15, 23, 42, 0.6) 100%);
        border: 1px solid rgba(147, 197, 253, 0.3);
        border-radius: 12px;
        padding: 12px 16px;
        color: #bae6fd;
        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        cursor: pointer;
      }

      .choice-item:hover {
        background: linear-gradient(135deg, rgba(30, 58, 95, 0.7) 0%, rgba(15, 23, 42, 0.8) 100%) !important;
        border-color: rgba(147, 197, 253, 0.5) !important;
        box-shadow:
          0 4px 20px rgba(147, 197, 253, 0.3),
          0 0 30px rgba(147, 197, 253, 0.2) !important;
        transform: translateX(4px);
      }

      .choice-item:active {
        transform: translateX(2px) scale(0.98) !important;
      }

      @keyframes stars-twinkle {
        0%,
        100% {
          opacity: 0.6;
        }
        50% {
          opacity: 1;
        }
      }
    </style>
  </head>
  <body>
    <div style="width: 80%; margin: 20px auto">
      <div class="star-choices">
        <div
          style="
            color: #e0f2fe;
            font-weight: 500;
            margin-bottom: 16px;
            display: flex;
            align-items: center;
            gap: 10px;
            position: relative;
            z-index: 2;
          "
        >
          <span style="font-size: 1.3em; filter: drop-shadow(0 0 14px rgba(147, 197, 253, 0.9))">🎲</span>
          <span>接下来要做什么？</span>
        </div>

        <div
          id="choice-list-container"
          style="display: flex; flex-direction: column; gap: 10px; position: relative; z-index: 2"
        ></div>

        <span
          style="
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-image:
              radial-gradient(circle at 20% 25%, rgba(147, 197, 253, 0.15) 1px, transparent 1px),
              radial-gradient(circle at 70% 55%, rgba(147, 197, 253, 0.12) 1px, transparent 1px),
              radial-gradient(circle at 40% 75%, rgba(147, 197, 253, 0.1) 1px, transparent 1px),
              radial-gradient(circle at 80% 30%, rgba(147, 197, 253, 0.13) 1px, transparent 1px);
            background-size: 100% 100%;
            animation: stars-twinkle 2s ease-in-out infinite;
            pointer-events: none;
            z-index: 1;
          "
        ></span>
      </div>
    </div>

    <script>
      (function () {
        function getCurrentMessageContent() {
          const _getChatMessages = window.getChatMessages || (window.parent && window.parent.getChatMessages);
          const _getCurrentMessageId =
            window.getCurrentMessageId || (window.parent && window.parent.getCurrentMessageId);

          if (typeof _getChatMessages === 'function' && typeof _getCurrentMessageId === 'function') {
            try {
              const msgId = _getCurrentMessageId();
              const msgs = _getChatMessages(msgId);
              if (msgs && msgs.length > 0) {
                return msgs[0].message;
              }
            } catch (e) {
              console.error('Error getting message content:', e);
            }
          }
          return null;
        }

        function parseChoices(content) {
          if (!content) return [];

          const blockRegex = /<choice>([\s\S]*?)<\/choice>/i;
          const match = content.match(blockRegex);
          if (!match) return [];

          const innerText = match[1];
          const lines = innerText.split('\n');
          const choices = [];

          lines.forEach(line => {
            const lineMatch = line.match(/^\s*(.*?)\s*-\s*(.*?)\s*$/);
            if (lineMatch) {
              choices.push({
                text: lineMatch[1].trim(),
                desc: lineMatch[2].trim(),
              });
            }
          });
          return choices;
        }

        function render() {
          const container = document.getElementById('choice-list-container');
          if (!container) return;

          const content = getCurrentMessageContent();
          if (!content) {
            container.innerHTML = '<div style="color: #94a3b8; text-align: center;">无法获取消息内容</div>';
            return;
          }

          const choices = parseChoices(content);
          if (choices.length === 0) {
            container.innerHTML = '<div style="color: #94a3b8; text-align: center;">解析失败或无选项</div>';
            return;
          }

          let html = '';
          choices.forEach((choice, index) => {
            let cleanText = choice.text.replace(/^\d+[\.\、\s]*/, '').trim();
            const sendText = cleanText + ' ' + choice.desc;
            const safeText = choice.text.replace(/"/g, '"').replace(/</g, '<').replace(/>/g, '>');
            const safeDesc = choice.desc.replace(/"/g, '"').replace(/</g, '<').replace(/>/g, '>');
            const safeSendText = sendText.replace(/"/g, '"').replace(/</g, '<').replace(/>/g, '>');
            html += `
                  <div class="choice-item" onclick="selectChoice(this)" data-send-text="${safeSendText}">
                    <strong class="choice-text">${safeText}</strong>
                    <span style="color: #94a3b8; font-size: 0.9em;"> - ${safeDesc}</span>
                  </div>
                `;
          });
          container.innerHTML = html;
        }

        window.selectChoice = function (element) {
          const text = element.getAttribute('data-send-text');
          if (!text) return;

          const _triggerSlash = window.triggerSlash || (window.parent && window.parent.triggerSlash);

          if (typeof _triggerSlash === 'function') {
            _triggerSlash('/setinput ' + text);
          } else {
            console.warn('triggerSlash not found');
          }
        };

        setTimeout(render, 100);
      })();
    </script>
  </body>
</html>
